@if($activeTab !== 'analytics')
@push('scripts')
<script>
    const activityForm=document.getElementById('activity-filter-form');const submitActivity=()=>activityForm.requestSubmit();let activitySearchTimer;document.getElementById('activity_search').addEventListener('input',()=>{clearTimeout(activitySearchTimer);activitySearchTimer=setTimeout(submitActivity,450)});
    const activityDropdown=document.querySelector('[data-activity-dropdown]');const roleInput=activityDropdown.querySelector('input');const roleMenu=activityDropdown.querySelector('.activity-dropdown-menu');activityDropdown.querySelector('[data-dropdown-trigger]').addEventListener('click',e=>{e.stopPropagation();activityDropdown.classList.toggle('is-open');roleMenu.classList.toggle('hidden')});roleMenu.querySelectorAll('[data-value]').forEach(option=>{option.classList.toggle('is-selected',option.dataset.value===roleInput.value);option.addEventListener('click',()=>{roleInput.value=option.dataset.value;submitActivity()})});
    const months=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];const datePickers=document.querySelectorAll('[data-activity-date]');const parseDate=value=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return null;const [y,m,d]=value.split('-').map(Number);return new Date(y,m-1,d)};const dateValue=date=>[date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-');const dateLabel=value=>{const date=parseDate(value);return date?new Intl.DateTimeFormat('es-ES',{day:'2-digit',month:'short',year:'numeric'}).format(date):'Seleccionar fecha'};const closeDates=()=>datePickers.forEach(p=>{p.classList.remove('is-open');p.querySelector('[data-date-calendar]').classList.add('hidden')});
    datePickers.forEach(picker=>{const input=picker.querySelector('input');const label=picker.querySelector('[data-date-label]');const calendar=picker.querySelector('[data-date-calendar]');const days=picker.querySelector('[data-days]');const title=picker.querySelector('[data-month]');let visible=parseDate(input.value)||new Date();visible=new Date(visible.getFullYear(),visible.getMonth(),1);label.textContent=dateLabel(input.value);const render=()=>{const y=visible.getFullYear(),m=visible.getMonth(),count=new Date(y,m+1,0).getDate(),offset=(new Date(y,m,1).getDay()+6)%7,from=document.getElementById('date_from').value,to=document.getElementById('date_to').value;title.textContent=`${months[m]} ${y}`;days.innerHTML='';for(let i=0;i<offset;i++)days.appendChild(document.createElement('span'));for(let d=1;d<=count;d++){const value=dateValue(new Date(y,m,d)),button=document.createElement('button');button.type='button';button.textContent=d;button.classList.toggle('selected',value===input.value);button.disabled=input.id==='date_from'?Boolean(to&&value>to):Boolean(from&&value<from);button.addEventListener('click',()=>{input.value=value;submitActivity()});days.appendChild(button)}};picker.querySelector('[data-date-trigger]').addEventListener('click',e=>{e.stopPropagation();closeDates();activityDropdown.classList.remove('is-open');roleMenu.classList.add('hidden');picker.classList.add('is-open');calendar.classList.remove('hidden');render()});calendar.addEventListener('click',e=>e.stopPropagation());picker.querySelector('[data-prev]').addEventListener('click',()=>{visible=new Date(visible.getFullYear(),visible.getMonth()-1,1);render()});picker.querySelector('[data-next]').addEventListener('click',()=>{visible=new Date(visible.getFullYear(),visible.getMonth()+1,1);render()});picker.querySelector('[data-clear]').addEventListener('click',()=>{input.value='';submitActivity()})});document.addEventListener('click',()=>{closeDates();activityDropdown.classList.remove('is-open');roleMenu.classList.add('hidden')});
</script>
@endpush
